        while (field_index < num_fields) {
            // Find the next comma or end of string
            end = start;
            while (*end != ',' && *end != '\0') {
                end++;
            }

            // Calculate field length (number of characters to copy)
            size_t field_len = (size_t)(end - start);
            int max_len = field_sizes[field_index] - 1; // leave room for null terminator
            if (field_len > (size_t)max_len) {
                field_len = (size_t)max_len; // truncate if necessary
            }

            // Compute destination offset in the buffer
            size_t record_offset = (size_t)i * total_field_size;
            size_t field_offset = 0;
            for (int k = 0; k < field_index; k++) {
                field_offset += (size_t)field_sizes[k];
            }
            char* dest = *parsed_buffer + record_offset + field_offset;

            // Copy the field content and null-terminate
            if (field_len > 0) {
                memcpy(dest, start, field_len);
            }
            dest[field_len] = '\0';

            // Move to the next field
            field_index++;
            if (*end == ',') {
                start = end + 1;
            } else {
                // End of record reached; if fewer fields than expected, pad remaining with empty strings
                while (field_index < num_fields) {
                    size_t pad_offset = 0;
                    for (int k = 0; k < field_index; k++) {
                        pad_offset += (size_t)field_sizes[k];
                    }
                    char* pad_dest = *parsed_buffer + record_offset + pad_offset;
                    pad_dest[0] = '\0';
                    field_index++;
                }
                break;
            }
        }
    }

    return 0;
}
